const CATALOG_KCAL = {"Gạo": 360, "Thịt bò": 250, "Thịt heo": 242, "Thịt gà": 215, "Trứng gà": 143, "Tôm": 99, "Cá basa": 90, "Đậu phụ": 76, "Lạc": 567, "Đậu xanh": 347, "Sữa tươi": 62, "Sữa chua": 61, "Chuối": 89, "Cam": 47, "Cà chua": 18, "Cà rốt": 41, "Bắp cải": 25, "Rau muống": 19, "Bí đỏ": 26, "Bông cải xanh": 34, "Cải thìa": 13, "Dưa leo": 15, "Gừng": 80, "Hành tây": 40, "Khoai tây": 77, "Nấm rơm": 32, "Táo": 52, "Thanh long": 60, "Tỏi": 149, "Đậu que": 31};

const lower = (list) => (list || []).map((value) => String(value).toLowerCase()).sort();
const fingerprint = (row) => ({
  calories: row.calories, protein: row.protein, carbs: row.carbs, fat: row.fat,
  ingredients: (row.ingredientDetails || []).map((entry) => [entry.name, entry.quantity ?? null, entry.unit ?? null]),
  steps: (row.steps || []).map((step) => step.instruction),
  allergens: lower(row.allergens), contraindications: lower(row.contraindications),
});
const same = (left, right) => JSON.stringify(left) === JSON.stringify(right);

(async () => {
  const login = await fetch(`${GATEWAY}/api/auth/login`, { method: "POST", headers: { "content-type": "application/json" }, body: JSON.stringify({ email: process.env.ADMIN_EMAIL, password: process.env.ADMIN_PASSWORD }) });
  const auth = await login.json().catch(() => ({}));
  const token = auth.accessToken ?? auth.data?.accessToken;
  if (!login.ok || !token) { console.log(`admin login failed (HTTP ${login.status})`); process.exit(1); }
  const call = async (method, path, data) => {
    const response = await fetch(`${GATEWAY}${path}`, { method, headers: { authorization: `Bearer ${token}`, "content-type": "application/json" }, body: data ? JSON.stringify(data) : undefined });
    const text = await response.text(); let json = null; try { json = JSON.parse(text); } catch {}
    return { status: response.status, json };
  };

  const recipes = (await call("GET", "/api/recipes")).json;
  if (!Array.isArray(recipes)) { console.log("could not list recipes"); process.exit(1); }
  const counts = { updated: 0, already: 0, skipped: 0, missing: 0, failed: 0 };
  console.log("== recipes");
  for (const fix of FIXES) {
    const row = recipes.find((entry) => entry.name === fix.name);
    if (!row) { counts.missing += 1; console.log(`${fix.name} | not found`); continue; }
    const now = fingerprint(row);
    if (same(now, fix.after)) { counts.already += 1; continue; }
    if (!same(now, fix.before)) { counts.skipped += 1; console.log(`${fix.name} | skipped: edited by an admin`); continue; }
    const result = await call("PUT", `/api/recipes/${encodeURIComponent(row.id)}`, fix.body);
    if (result.status === 200) { counts.updated += 1; console.log(`${fix.name} | updated`); }
    else { counts.failed += 1; console.log(`${fix.name} | failed (HTTP ${result.status})`); }
  }
  console.log(`recipes: ${counts.updated} updated, ${counts.already} already applied, ${counts.skipped} skipped, ${counts.missing} not found, ${counts.failed} failed`);

  console.log("== catalog kcal per 100 g");
  const catalog = (await call("GET", "/api/admin/ingredients/export")).json;
  if (!Array.isArray(catalog)) { console.log("could not export the catalog"); process.exit(1); }
  let changed = 0;
  for (const [name, kcal] of Object.entries(CATALOG_KCAL)) {
    const row = catalog.find((entry) => entry.name === name);
    if (!row || row.caloriesPer100g !== 50) continue;
    const result = await call("PUT", `/api/admin/ingredients/${row.id}`, { caloriesPer100g: kcal });
    console.log(`${name} | 50 -> ${kcal} | ${result.status === 200 ? "ok" : `failed (HTTP ${result.status})`}`);
    if (result.status === 200) changed += 1;
  }
  console.log(`catalog: ${changed} rows updated`);
})().catch((error) => { console.log(`error: ${error.message}`); process.exit(1); });
